package com.ppms.admin.service;
import com.ppms.admin.api.workforce.WorkforceDtos.*;import com.ppms.admin.domain.workforce.Certification;import com.ppms.admin.repositories.workforce.*;import com.ppms.shared.exception.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @RequiredArgsConstructor public class CertificationService {private final CertificationRepository repository;private final EmployeeRepository employees;@Transactional(readOnly=true)public List<CertificationDto> list(UUID employeeId){requireEmployee(employeeId);return repository.findByEmployeeId(employeeId).stream().map(this::dto).toList();}@Transactional public CertificationDto create(UUID employeeId,CertificationRequest r){requireEmployee(employeeId);return dto(repository.save(apply(new Certification(),employeeId,r)));}@Transactional public CertificationDto update(UUID employeeId,UUID id,CertificationRequest r){Certification c=find(employeeId,id);return dto(apply(c,employeeId,r));}@Transactional public void delete(UUID employeeId,UUID id){repository.delete(find(employeeId,id));}private Certification find(UUID employeeId,UUID id){Certification c=repository.findById(id).orElseThrow(()->new EntityNotFoundException("Certification",id));if(!c.getEmployeeId().equals(employeeId))throw new EntityNotFoundException("Certification",id);return c;}private void requireEmployee(UUID id){if(!employees.existsById(id))throw new EntityNotFoundException("Employee",id);}private Certification apply(Certification c,UUID employeeId,CertificationRequest r){c.setEmployeeId(employeeId);c.setType(r.type());c.setNumber(r.number());c.setIssuedAt(r.issuedAt());c.setExpiresAt(r.expiresAt());c.setDocumentRef(r.documentRef());return c;}private CertificationDto dto(Certification c){return new CertificationDto(c.getId(),c.getEmployeeId(),c.getType(),c.getNumber(),c.getIssuedAt(),c.getExpiresAt(),c.getDocumentRef());}}
